import { Text, View } from '@tarojs/components';

import './vehicle-summary.less';

type VehicleSummaryProps = {
  disabled: boolean;
  price: string;
  title: string;
};

export function VehicleSummary({ disabled, price, title }: VehicleSummaryProps) {
  return (
    <View className={disabled ? 'vehicle-summary vehicle-summary--disabled' : 'vehicle-summary'}>
      <Text className="vehicle-summary__title">{title}</Text>
      <Text className="vehicle-summary__price">{price}</Text>
    </View>
  );
}

